
const state={events:[],filtered:[],month:new Date(),format:'All',topic:'',query:''};
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const dateOnly=s=>s.length===10; const dateOf=s=>new Date(dateOnly(s)?s+'T12:00:00':s);
function fmtDate(s,opts={}){return new Intl.DateTimeFormat('en-NL',{day:'numeric',month:'short',year:'numeric',...opts}).format(dateOf(s))}
function sameDay(a,b){return a.getFullYear()===b.getFullYear()&&a.getMonth()===b.getMonth()&&a.getDate()===b.getDate()}
function applyFilters(){const q=state.query.toLowerCase();state.filtered=state.events.filter(e=>{const hay=[e.title,e.location,e.description,...e.topics].join(' ').toLowerCase(),formatMatch=state.format==='All'||(state.format==='Free'?e.cost.toLowerCase().includes('free'):state.format==='In person'?e.format!=='Online':e.format===state.format);return(!q||hay.includes(q))&&(!state.topic||e.topics.includes(state.topic))&&formatMatch});render()}
const todayPage=location.pathname.endsWith('/today.html');
const comingUpPage=location.pathname.endsWith('/coming-up.html');
function render(){if(todayPage){renderToday();return}if(comingUpPage){renderComingUp();return}renderCalendar();renderSide();}
function renderCalendar(){const y=state.month.getFullYear(),m=state.month.getMonth();$('#monthTitle').textContent=new Intl.DateTimeFormat('en-NL',{month:'long',year:'numeric'}).format(state.month);const first=new Date(y,m,1),offset=(first.getDay()+6)%7,start=new Date(y,m,1-offset);let html='';for(let i=0;i<42;i++){const d=new Date(start);d.setDate(start.getDate()+i);const events=eventsOnDay(state.filtered,[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-'));html+=`<div class="day ${d.getMonth()!==m?'out':''} ${sameDay(d,new Date())?'today':''}"><div class="num">${d.getDate()}</div>${events.slice(0,1).map(e=>`<button class="event-pill ${e.format==='Online'?'online':''}" data-id="${e.id}" title="${esc(e.title)}">${esc(e.title)}</button>`).join('')}${events.length>1?`<button class="more" data-day="${dayKey([d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-'))}">+${events.length-1} more</button>`:''}</div>`}$('#calendar').innerHTML=html;document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>openEvent(b.dataset.id));document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{const day=eventsOnDay(state.filtered,b.dataset.day);$('#detail').innerHTML=`<div class="detail-top"><div><span class="badge">${fmtDate(b.dataset.day)}</span><h2>Events on this day</h2></div><button class="close" aria-label="Close">×</button></div><div class="next-list">${eventList(day)}</div>`;$('#eventDialog').showModal();$('.close').onclick=()=>$('#eventDialog').close();document.querySelectorAll('#detail .next').forEach(item=>item.onclick=()=>openEvent(item.dataset.id))})}
function eventList(items){return items.map(e=>{const d=dateOf(e.start);return `<article class="next" data-id="${e.id}" tabindex="0"><div class="datebox"><b>${d.getDate()}</b><span>${d.toLocaleString('en',{month:'short'})}</span></div><div><h3>${esc(e.title)}</h3><p>${esc(e.format)} Â· ${esc(e.location)}</p></div></article>`}).join('')||'<p class="note">No matching events.</p>'}
function isUpcoming(e,now=new Date()){return dayKey(e.end||e.start)>=dayKey(now)}
function dayKey(value){if(typeof value==='string'&&dateOnly(value))return value;const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Amsterdam',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date(value));const part=type=>parts.find(p=>p.type===type).value;return `${part('year')}-${part('month')}-${part('day')}`}
function eventsOnDay(events,day){const key=dayKey(day);return events.filter(e=>e.scheduleType==='series'?(e.sessionDates||[]).some(date=>dayKey(date)===key):dayKey(e.start)<=key&&dayKey(e.end||e.start)>=key).sort((a,b)=>dateOf(a.start)-dateOf(b.start))}
function renderToday(){const now=new Date(),events=eventsOnDay(state.events,now);$('#todayTitle').textContent=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Amsterdam',weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(now);$('#todayCount').textContent=`${events.length} events · Netherlands time (Europe/Amsterdam)`;$('#todayList').innerHTML=events.map(e=>`<article class="today-card"><span class="badge">${esc(e.format)}</span><h2>${esc(e.title)}</h2><p>${esc(e.location)}</p><p>${dateOnly(e.start)?'All day / time not specified':new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Amsterdam',hour:'2-digit',minute:'2-digit'}).format(dateOf(e.start))}${dayKey(e.start)!==dayKey(e.end||e.start)?' · '+fmtDate(e.start)+' to '+fmtDate(e.end):''}</p><p>${esc(e.description)}</p><button data-id="${esc(e.id)}">View details</button></article>`).join('')||'<p class="empty">No events scheduled for today.</p>';document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>openEvent(b.dataset.id))}
function goToToday(){location.assign('./today.html')}
function refreshDate(){const today=dayKey(new Date());if(today!==lastRenderedDate){lastRenderedDate=today;render()}}
let lastRenderedDate=dayKey(new Date());
function comingUpUrl(){const params=new URLSearchParams();if(state.query)params.set('q',state.query);if(state.topic)params.set('topic',state.topic);if(state.format!=='All')params.set('format',state.format);return './coming-up.html'+(params.size?'?'+params.toString():'')}
function renderComingUp(){const today=new Date(),end=new Date(today);end.setDate(end.getDate()+7);const todayKey=dayKey(today),endKey=dayKey(end);const events=state.filtered.filter(e=>isUpcoming(e,today)&&dayKey(e.start)<=endKey&&dayKey(e.end||e.start)>=todayKey).sort((a,b)=>dateOf(a.start)-dateOf(b.start));$('#comingUpCount').textContent=`${events.length} upcoming events`;$('#activeFilters').textContent=[state.query&&`Search: ${state.query}`,state.topic&&`Topic: ${state.topic}`,state.format!=='All'&&state.format].filter(Boolean).join(' · ')||'Netherlands and online events';$('#comingUpList').innerHTML=eventList(events);document.querySelectorAll('.next').forEach(x=>{x.onclick=()=>openEvent(x.dataset.id);x.onkeydown=e=>{if(e.key==='Enter')openEvent(x.dataset.id)}})}
function renderSide(){const list=[...state.filtered].sort((a,b)=>dateOf(a.start)-dateOf(b.start)),inNl=list.filter(e=>e.format!=='Online'),online=list.filter(e=>e.format==='Online');$('#eventCount').textContent=list.length;$('#nlCount').textContent=inNl.length;$('#freeCount').textContent=list.filter(e=>e.cost.toLowerCase().includes('free')).length;const today=new Date(),end=new Date(today);end.setDate(end.getDate()+7);const upcoming=list.filter(e=>isUpcoming(e,today)&&dayKey(e.start)<=dayKey(end)&&dayKey(e.end||e.start)>=dayKey(today));$('#upcoming').innerHTML=eventList(upcoming.slice(0,5));const toggle=$('#showAllUpcoming');toggle.hidden=upcoming.length<=5;toggle.textContent=`Show all (${upcoming.length})`;toggle.href=comingUpUrl();document.querySelectorAll('.next').forEach(x=>{x.onclick=()=>openEvent(x.dataset.id);x.onkeydown=e=>{if(e.key==='Enter')openEvent(x.dataset.id)}})}
function openEvent(id){const e=state.events.find(x=>x.id===id);if(!e)return;$('#detail').innerHTML=`<div class="detail-top"><div><span class="badge">${esc(e.format)}</span><h2>${esc(e.title)}</h2></div><button class="close" aria-label="Close">Ã—</button></div><p>${esc(e.description)}</p><div class="meta"><div><small>Date</small><strong>${fmtDate(e.start)}${e.end&&e.end.slice(0,10)!==e.start.slice(0,10)?' to '+fmtDate(e.end):''}</strong></div><div><small>Location</small><strong>${esc(e.location)}</strong></div><div><small>Cost</small><strong>${esc(e.cost)}</strong></div><div><small>Language</small><strong>${esc(e.language)}</strong></div></div><p class="note">${esc(e.topics.join(' Â· '))}<br>Verified ${fmtDate(e.verified)} via ${esc(e.source)}</p><div class="detail-actions"><a class="source" href="${esc(e.url)}" target="_blank" rel="noopener">View source</a><a class="ics" href="#" id="oneIcs">Add to calendar</a></div>`;$('#eventDialog').showModal();$('.close').onclick=()=>$('#eventDialog').close();$('#oneIcs').onclick=x=>{x.preventDefault();downloadICS([e])}}
function icsDate(s){if(dateOnly(s))return s.replaceAll('-','');return new Date(s).toISOString().replace(/[-:]/g,'').replace('.000','')}
function downloadICS(events){const rows=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Cloud Calendar NL//EN','CALSCALE:GREGORIAN'];events.forEach(e=>{rows.push('BEGIN:VEVENT','UID:'+e.id+'@cloudcalendar.nl','DTSTAMP:'+icsDate(new Date().toISOString()),(dateOnly(e.start)?'DTSTART;VALUE=DATE:':'DTSTART:')+icsDate(e.start),(dateOnly(e.end)?'DTEND;VALUE=DATE:':'DTEND:')+icsDate(e.end||e.start),'SUMMARY:'+e.title.replace(/,/g,'\\,'),'LOCATION:'+e.location.replace(/,/g,'\\,'),'DESCRIPTION:'+e.description.replace(/,/g,'\\,')+'\\n'+e.url,'URL:'+e.url,'END:VEVENT')});rows.push('END:VCALENDAR');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([rows.join('\r\n')],{type:'text/calendar'}));a.download='cloud-calendar-nl.ics';a.click();URL.revokeObjectURL(a.href)}
function init(){const data=window.CLOUD_CALENDAR_EVENTS;if(!data?.events?.length)throw new Error('Event data is unavailable');state.events=data.events;state.filtered=data.events;if(todayPage){renderToday();return}if(comingUpPage){const params=new URLSearchParams(location.search);state.query=params.get('q')||'';state.topic=params.get('topic')||'';state.format=params.get('format')||'All';applyFilters();return}const today=new Date();state.month=new Date(today.getFullYear(),today.getMonth(),1);$('#updatedLabel').textContent=`Checked ${fmtDate(data.lastUpdated)}`;const topics=[...new Set(state.events.flatMap(e=>e.topics))].sort();$('#topic').innerHTML+=topics.map(t=>`<option>${esc(t)}</option>`).join('');applyFilters()}
if(!todayPage&&!comingUpPage){$('#search').oninput=e=>{state.query=e.target.value;applyFilters()};$('#topic').onchange=e=>{state.topic=e.target.value;applyFilters()};document.querySelectorAll('.chip').forEach(b=>b.onclick=()=>{document.querySelectorAll('.chip').forEach(x=>x.classList.remove('active'));b.classList.add('active');state.format=b.dataset.format;applyFilters()});$('#prev').onclick=()=>{state.month=new Date(state.month.getFullYear(),state.month.getMonth()-1,1);renderCalendar()};$('#next').onclick=()=>{state.month=new Date(state.month.getFullYear(),state.month.getMonth()+1,1);renderCalendar()};$('#todayBtn').onclick=goToToday;$('#downloadAll').onclick=()=>downloadICS(state.filtered);}$('#eventDialog').onclick=e=>{if(e.target.id==='eventDialog')e.target.close()};setInterval(refreshDate,30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshDate()});window.addEventListener('pageshow',refreshDate);try{init()}catch(error){console.error(error);if($('#updatedLabel'))$('#updatedLabel').textContent='Could not load events';$(todayPage?'#todayList':comingUpPage?'#comingUpList':'#calendar').innerHTML='<div class="empty">The event feed could not be loaded.</div>'}
